package com.quincaisoft.documents.application;
import com.quincaisoft.documents.api.DocumentsBootstrapService;import com.quincaisoft.documents.infrastructure.*;import com.quincaisoft.shared.BootstrapScope;import jakarta.persistence.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.util.*;import java.time.*;
@Service public class DefaultDocumentsBootstrapService implements DocumentsBootstrapService { private final EntityManager em; public DefaultDocumentsBootstrapService(EntityManager em){this.em=em;}
@Transactional(propagation=Propagation.MANDATORY) public void initialize(BootstrapScope s,String issuer,String address,String registration,String prefix,String locale,int year) {require(s);var d=new DocumentSettings();d.tenantId=s.tenantId();d.companyId=s.companyId();d.branchId=s.branchId();d.issuerName=issuer;d.issuerAddress=address;d.registrationNumber=registration;d.fiscalSeries=prefix;d.locale=locale;d.version=1;em.persist(d);for(String kind:List.of("INVOICE","CREDIT_NOTE","QUOTATION")){var n=new DocumentSeries();n.tenantId=s.tenantId();n.companyId=s.companyId();n.branchId=s.branchId();n.kind=kind;n.fiscalSeries=prefix+"-"+year;n.nextNumber=1;em.persist(n);}em.flush();}
private void require(BootstrapScope s) { if(!em.isJoinedToTransaction()) throw new IllegalStateException("Bootstrap must join platform transaction"); Number n=(Number)em.createNativeQuery(BootstrapScope.AUTHORIZATION_SQL).setParameter("p",s.provisioningId()).setParameter("t",s.tenantId()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("o",s.ownerId()).getSingleResult(); if(n.longValue()!=1)throw new org.springframework.security.access.AccessDeniedException("Approved current platform bootstrap required"); }
}
